package add_adapter

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "add_adapter"
	command.Identifiers = []string{"add-adapter"}
	command.Category = "Deps System"
	command.Help = "Installs one further adapter for a contract the project already has"
	command.LongDescription = "Renders assets/adapterlist/<adapter> into the project and writes its declaration to adapters/libs/<adapter>/adapter.yaml. The contract it fills has to be installed already. Installing changes no selection: an available binds one adapter per field, so --available names the one that switches to it."
	command.Examples = []string{"add-adapter reflectsort", "add-adapter reflectsort --available lambda"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "available",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the available that should switch to this adapter (installs only when absent)",
			Examples:    []string{"add-adapter reflectsort --available lambda"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--available"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"add-adapter reflectsort --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"add-adapter reflectsort -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "adapter",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the adapter to install from assets/adapterlist",
			Examples:    []string{"add-adapter reflectsort"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
